"""Real terminal demos (generated by sh_runner.demo) used inside OS Unit 5 notes."""
import html
from sh_runner import demo

STUDENTS = """Ravi CE 78
Priya IT 92
Amit CE 65
Neha ME 88
Karan CE 71
Sneha IT 84
Arjun EE 59
Pooja CE 95
Vivek ME 67
Anjali IT 73
"""
F1 = "apple\nbanana\ncherry\nmango\n"
F2 = "apple\nbanana\ngrape\nmango\norange\n"
HELLO_C = '#include <stdio.h>\nint main()\n{\n    printf("Hello, Linux!\\n");\n    return 0;\n}\n'


def pre(s):
    return '<pre class="c">' + html.escape(s) + "</pre>"


DIRS = demo(["pwd", "mkdir os", "mkdir -p sem3/os/unit5", "ls", "ls -a", "ls -l", "cd sem3/os", "pwd", "cd ..", "pwd", "cd ~",
             "rmdir os", "ls -R sem3", "rmdir sem3"],
            files={"notes.txt": "Linux notes\nUnit 5\n", "prog.c": HELLO_C, ".profile": "# hidden\n"})

FILES = demo(["cat a.txt", "cat -n a.txt b.txt", "cat a.txt b.txt > c.txt", "cp a.txt a_copy.txt", "ls", "mv a_copy.txt backup.txt",
              "mkdir old", "mv c.txt old/", "ls", "ls old", "rm backup.txt", "rm -r old", "ls"],
             files={"a.txt": "Operating System\nLinux commands\n", "b.txt": "GTU Diploma\n"})

WC = demo(["wc students.txt", "wc -l students.txt", "wc -w -c students.txt", "head -3 students.txt", "tail -2 students.txt",
           "split -l 4 students.txt part_", "ls", "cat part_ac"], files={"students.txt": STUDENTS})

CMP = demo(["cat f1.txt", "cat f2.txt", "cmp f1.txt f2.txt", "cmp f1.txt f1.txt && echo same", "comm f1.txt f2.txt", "comm -12 f1.txt f2.txt",
            "diff f1.txt f2.txt"], files={"f1.txt": F1, "f2.txt": F2})

GREP = demo(["grep CE students.txt", "grep -i ravi students.txt", "grep -c CE students.txt", "grep -v -e CE -e IT students.txt",
             "grep -n '^A' students.txt", "grep -l Ravi *.txt"], files={"students.txt": STUDENTS, "notes.txt": "Ravi wrote notes\n"})

SORT = demo(["sort students.txt | head -4", "sort -r students.txt | head -3", "sort -k3 -n students.txt | head -3",
             "sort -k3 -nr students.txt | head -3", "cut -d' ' -f2 students.txt | sort | uniq -c"], files={"students.txt": STUDENTS})

SHELL = demo(["echo $SHELL", "echo Hello > h.txt", "echo World >> h.txt", "cat h.txt", "wc -l < h.txt", "ls | wc -l", "ls *.txt",
              "name=Ravi; echo \"Hi $name\"", "echo 'Hi $name'"], files={"a.txt": "x\n", "b.c": "y\n"})

GCC = demo(["cat hello.c", "gcc hello.c", "ls", "./a.out", "gcc hello.c -o hello", "./hello"], files={"hello.c": HELLO_C})

if __name__ == "__main__":
    for k in ("DIRS", "FILES", "WC", "CMP", "GREP", "SORT", "SHELL", "GCC"):
        print("=" * 8, k)
        print(globals()[k])
